```suggestion
    PyObject *str = PyUnicode_New(2, _Py_MAX_UNICODE);
    if (str == NULL) {
        return NULL;
    }
    PyUnicode_4BYTE_DATA(str)[0] = _Py_MAX_UNICODE + 1;
    PyUnicode_4BYTE_DATA(str)[1] = _Py_MAX_UNICODE + 2;
```

